from pathlib import Path
import base64

ROOT = Path(__file__).resolve().parents[1]
TARGET = ROOT / "build/generated/metatech_assets/assets/metatech_reborn/textures/item"

TEXTURES = {
    "mana_drill_generation_upgrade.png": "",
    "mana_drill_looting_upgrade.png": "",
    "mana_drill_module.png": "",
    "mana_drill_speed_upgrade.png": "",
    "neutron_combiner_efficiency_upgrade.png": "",
    "neutron_combiner_output_upgrade.png": "",
    "neutron_combiner_speed_upgrade.png": ""
}

TARGET.mkdir(parents=True, exist_ok=True)
for name, encoded in TEXTURES.items():
    (TARGET / name).write_bytes(base64.b64decode(encoded))

print(f"Installed {len(TEXTURES)} refreshed item textures")
